// pages/Feed.jsx
import React, { useEffect, useState } from 'react';
import ReviewCard from '../components/ReviewCard';
import Composer from '../components/Composer';
import { fetchReviews, createReview } from '../api/reviewApi';
import { useAuth } from '../hooks/useAuth';

// Feed: SNS-style feed with advanced Composer (multi-file, drag-drop, crop/filter)

function Feed() {
  const [reviews, setReviews] = useState([]);

  const { user, updateUserPoints } = useAuth();

  const saveAndPrepend = (item) => {
    setReviews(prev => [item, ...prev]);
  };

  const handleComposerSubmit = async ({ author, text, files, tags }) => {
    const payload = {
      author: { username: author || '익명' },
      title: '',
      text,
      images: (files || []).map(f => f.dataUrl),
      tags: tags || [],
    };
    try {
      const res = await createReview(payload);
      const created = res.data;
      saveAndPrepend(created);

      // If the current logged-in user is the author, update AuthContext points from localStorage
      if (created.awardedPoints && user && user.username === payload.author.username) {
        // read updated session user from localStorage (reviewApi updated it)
        try {
          const saved = JSON.parse(localStorage.getItem('user') || 'null');
          if (saved && typeof saved.points === 'number') updateUserPoints(saved.points);
        } catch (e) { /* ignore */ }
      }
    } catch (err) {
      console.error('create review failed', err);
      alert('업로드에 실패했습니다');
    }
  };

  useEffect(() => {
    const load = async () => {
      try {
        const res = await fetchReviews({ page: 1, limit: 20 });
        setReviews(res.data);
      } catch (err) {
        console.error('fetch reviews', err);
      }
    };
    load();
  }, []);

  return (
    <div style={{ padding: 20 }}>
      <h1>📝 리뷰 피드</h1>
      <p style={{ color: '#666' }}>사용자들이 올린 최신 리뷰를 확인하세요.</p>

      {/* Composer */}
      <div style={{ marginTop: 16, marginBottom: 18 }}>
        <Composer onSubmit={handleComposerSubmit} initialAuthor="" />
      </div>

      <div style={{ marginTop: 16 }}>
        {reviews.length === 0 ? (
          <p style={{ color: '#999' }}>아직 리뷰가 없습니다.</p>
        ) : (
          reviews.map(r => (
            <ReviewCard key={r._id} id={r._id} username={r.author?.username || '익명'} title={r.title} text={r.text} images={r.images} createdAt={r.createdAt} likes={r.likes} />
          ))
        )}
      </div>
    </div>
  );
}

export default Feed;
